it('counts abilitiesMany queries with tenancy on', function (): void {
    config()->set('vaulter.tenancy.enabled', true);
    config()->set('vaulter.tenancy.resolver', MutableTenantResolver::class);
    app()->instance(TenantResolver::class, new MutableTenantResolver);

    $drive = V1::drive(userId: 1);
    $ids = [];
    foreach (range(1, 8) as $i) {
        $ids[] = V1::folder($drive, 'n'.$i)->id;
    }
    $nodes = $drive->actingAs(V1::user(1))->nodes();

    $count = function (array $slice) use ($nodes): array {
        DB::flushQueryLog();
        DB::enableQueryLog();
        $result = $nodes->abilitiesMany($slice);
        $log = DB::getQueryLog();
        DB::disableQueryLog();

        return [count($log), count($result), array_map(static fn (array $q): string => $q['query'], $log)];
    };

    [$smallN, $smallOut, $smallSql] = $count(array_slice($ids, 0, 2));
    [$largeN, $largeOut, $largeSql] = $count($ids);

    fwrite(STDOUT, "small_queries=$smallN small_out=$smallOut\n");
    fwrite(STDOUT, "large_queries=$largeN large_out=$largeOut\n");
    fwrite(STDOUT, "SMALL SQL:\n".implode("\n", $smallSql)."\n");
    fwrite(STDOUT, "LARGE SQL:\n".implode("\n", $largeSql)."\n");

    expect($largeOut)->toBe(8);
});
